def solve(n):
    """Return the number of primes strictly less than n."""
    if n <= 2:
        return 0
    # Sieve of Eratosthenes up to n-1
    limit = n  # we need primes < n, i.e. up to n-1
    is_prime = [True] * limit
    is_prime[0] = False
    if limit > 1:
        is_prime[1] = False
    i = 2
    while i * i < limit:
        if is_prime[i]:
            for j in range(i * i, limit, i):
                is_prime[j] = False
        i += 1
    return sum(is_prime)

