def solve(coins, amount):
    # DP for coin change (unlimited supply). Return min number of coins, or -1.
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Initialize dp array with amount+1 (inf)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        min_cnt = INF
        for c in coins:
            if c <= a:
                cnt = dp[a - c] + 1
                if cnt < min_cnt:
                    min_cnt = cnt
        dp[a] = min_cnt
    return dp[amount] if dp[amount] != INF else -1

