def solve(weights, values, capacity):
    """0/1 knapsack: maximize total value without exceeding capacity.
    Uses one‑dimensional DP updating backwards.
    """
    n = len(weights)
    if capacity <= 0 or n == 0:
        return 0
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        if w > capacity:
            # item too heavy, skip
            continue
        for c in range(capacity, w - 1, -1):
            cand = dp[c - w] + v
            if cand > dp[c]:
                dp[c] = cand
    return dp[capacity]

