{"task_id": "T13", "code": "def solve(coins, amount):
    # Dynamic programming for unlimited coin change.
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= a:
