import itertools, heapq, random, sys

def solve_ref(n, edges):
    # brute force: generate all permutations, check if topological
    indeg = [0]*n
    adj = [[] for _ in range(n)]
    for a,b in edges:
        adj[a].append(b)
        indeg[b]+=1
    best=None
    for perm in itertools.permutations(range(n)):
        ok=True
        pos={v:i for i,v in enumerate(perm)}
        for a in range(n):
            for b in adj[a]:
                if pos[a]>=pos[b]:
                    ok=False;break
            if not ok:
                break
        if ok:
            if best is None or perm<best:
                best=perm
    return list(best) if best is not None else []

def solve_my(n, edges):
    seen=set()
    adj=[[] for _ in range(n)]
    indeg=[0]*n
    for a,b in edges:
        if not (0<=a<n and 0<=b<n):
            continue
        if (a,b) in seen:
            continue
        seen.add((a,b))
        adj[a].append(b)
        indeg[b]+=1
    heap=[i for i in range(n) if indeg[i]==0]
    heapq.heapify(heap)
    order=[]
    while heap:
        u=heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v]-=1
            if indeg[v]==0:
                heapq.heappush(heap,v)
    return order if len(order)==n else []

def test():
    for n in range(1,6):
        nodes=list(range(n))
        all_possible=[(i,j) for i in nodes for j in nodes if i!=j]
        for _ in range(200):
            edges=random.sample(all_possible, random.randint(0,len(all_possible)))
            ref=solve_ref(n,edges)
            my=solve_my(n,edges)
            if ref!=my:
                print('Mismatch',n,edges,ref,my)
                return False
    print('All good')
    return True

test()

