    """Count islands of 1's in a grid.
    Does not modify the input grid. Cells are connected orthogonally.
    """
    if not grid:
        return 0
    visited = set()
    count = 0
    rows = len(grid)
    for i in range(rows):
        cols = len(grid[i])
        for j in range(cols):
            if grid[i][j] == 1 and (i, j) not in visited:
                count += 1
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) in visited:
                        continue
                    if 0 <= x < len(grid) and 0 <= y < len(grid[x]) and grid[x][y] == 1:
                        visited.add((x, y))
                        stack.append((x + 1, y))
                        stack.append((x - 1, y))
                        stack.append((x, y + 1))
                        stack.append((x, y - 1))
    return count

