def solve(coins, amount):
    # robust coin change with DP, handling edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # keep only positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    coins.sort()
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = INF
        for c in coins:
            if c > a:
