    """Return the minimum total weight from node 0 to node n-1 in an undirected graph.
    If n == 0 return -1. If n == 1 return 0 (trivial path). If no path exists return -1.
    Edges with endpoints outside the range [0, n-1] are ignored.
    """
    import heapq
    if n <= 0:
        return -1
    if n == 1:
        return 0
    # Build adjacency list, safely ignoring malformed edges
    adj = [[] for _ in range(n)]
    for edge in edges:
        if len(edge) != 3:
            continue
        a, b, w = edge
        # Validate indices and weight
        if not (isinstance(a, int) and isinstance(b, int) and isinstance(w, (int, float))):
            continue
        if a < 0 or a >= n or b < 0 or b >= n:
            continue
        # Positive weights as per spec, but ignore non‑positive to avoid zero‑weight cycles
        if w <= 0:
            continue
        adj[a].append((b, w))
        adj[b].append((a, w))
    # Dijkstra's algorithm
    dist = [float('inf')] * n
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
