def solve(s):
    """Return the length of the longest substring of s without repeated
    characters (sliding window)."""
    last = {}
    start = 0
    best = 0
    for i, ch in enumerate(s):
        if ch in last and last[ch] >= start:
            start = last[ch] + 1
        last[ch] = i
        window = i - start + 1
        if window > best:
            best = window
    return best

